773→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
774→// Returns an empty string if the prompt cannot be read.
775→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
776→	// Get the commit and its tree
777→	commit, err := repo.CommitObject(commitHash)
778→	if err != nil {
779→		return ""
780→	}
781→
782→	tree, err := commit.Tree()
783→	if err != nil {
784→		return ""
785→	}
786→
787→	// Look for prompt.txt in the metadata directory
788→	promptPath := metadataDir + "/" + paths.PromptFileName
789→	promptEntry, err := tree.File(promptPath)
790→	if err != nil {
791→		return ""
792→	}
793→
794→	content, err := promptEntry.Contents()
795→	if err != nil {
796→		return ""
797→	}
798→
799→	return ExtractFirstPrompt(content)
800→}
