821→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
822→// about each session, including whether local logs have newer timestamps.
823→// repoRoot is used to compute per-session agent directories.
824→// Sessions without agent metadata are skipped (cannot determine target directory).
825→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
826→	var sessions []SessionRestoreInfo
827→
828→	totalSessions := len(summary.Sessions)
829→	// Check all sessions (0-based indexing)
830→	for i := range totalSessions {
831→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
832→		if err != nil || content == nil || len(content.Transcript) == 0 {
833→			continue
834→		}
835→
836→		sessionID := content.Metadata.SessionID
837→		if sessionID == "" || content.Metadata.Agent == "" {
838→			continue
839→		}
840→
841→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
842→		if agErr != nil {
843→			continue
844→		}
845→
846→		// Compute transcript path from current repo location for cross-machine portability.
847→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
848→		if dirErr != nil {
849→			continue
850→		}
851→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
852→
853→		localTime := paths.GetLastTimestampFromFile(localPath)
854→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
855→		status := ClassifyTimestamps(localTime, checkpointTime)
856→
857→		sessions = append(sessions, SessionRestoreInfo{
858→			SessionID:      sessionID,
859→			Prompt:         ExtractFirstPrompt(content.Prompts),
860→			Status:         status,
861→			LocalTime:      localTime,
862→			CheckpointTime: checkpointTime,
863→		})
864→	}
865→
866→	return sessions
867→}
868→
869→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
870→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
871→	// Local file doesn't exist (no timestamp found)
872→	if localTime.IsZero() {
873→		return StatusNew
874→	}
875→
876→	// Can't determine checkpoint time - treat as new/safe
877→	if checkpointTime.IsZero() {
878→		return StatusNew
879→	}
880→
881→	// Compare timestamps
882→	if localTime.After(checkpointTime) {
883→		return StatusLocalNewer
884→	}
885→	if checkpointTime.After(localTime) {
886→		return StatusCheckpointNewer
887→	}
888→	return StatusUnchanged
889→}
890→
891→// StatusToText returns a human-readable status string.
892→func StatusToText(status SessionRestoreStatus) string {
893→	switch status {
894→	case StatusNew:
895→		return "(new)"
896→	case StatusUnchanged:
897→		return "(unchanged)"
898→	case StatusCheckpointNewer:
899→		return "(checkpoint is newer)"
900→	case StatusLocalNewer:
901→		return "(local is newer)" // shouldn't appear in non-conflict list
902→	default:
903→		return ""
904→	}
905→}
906→
907→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
908→// session logs that have newer timestamps than the checkpoint versions.
909→func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
910→	// Separate conflicting and non-conflicting sessions
911→	var conflicting, nonConflicting []SessionRestoreInfo
912→	for _, s := range sessions {
913→		if s.Status == StatusLocalNewer {
914→			conflicting = append(conflicting, s)
915→		} else {
916→			nonConflicting = append(nonConflicting, s)
917→		}
918→	}
919→
920→	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
921→	for _, info := range conflicting {
922→		// Show prompt if available, otherwise fall back to session ID
923→		if info.Prompt != "" {
924→			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
925→		} else {
926→			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
927→		}
928→		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
929→		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
930→	}
931→
932→	// Show non-conflicting sessions with their status
933→	if len(nonConflicting) > 0 {
934→		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
935→		for _, info := range nonConflicting {
936→			statusText := StatusToText(info.Status)
937→			if info.Prompt != "" {
938→				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
939→			} else {
940→				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
941→			}
942→		}
943→	}
944→
945→	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")
946→
947→	var confirmed bool
948→	form := huh.NewForm(
949→		huh.NewGroup(
950→			huh.NewConfirm().
951→				Title("Overwrite local session logs with checkpoint versions?").
952→				Value(&confirmed),
953→		),
954→	)
955→	if isAccessibleMode() {
956→		form = form.WithAccessible(true)
957→	}
958→
959→	if err := form.Run(); err != nil {
960→		if errors.Is(err, huh.ErrUserAborted) {
961→			return false, nil
962→		}
963→		return false, fmt.Errorf("failed to get confirmation: %w", err)
964→	}
965→
966→	return confirmed, nil
967→}
